<?php require 'config/database.php'; $pageTitle='Enrollments'; if(isset($_GET['delete'])){$q=$pdo->prepare('DELETE FROM enrollments WHERE id=?');$q->execute([(int)$_GET['delete']]);header('Location: enrollments.php');exit;} $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){try{$q=$pdo->prepare('INSERT INTO enrollments(student_id,course_id,enrolled_on) VALUES(?,?,?)');$q->execute([(int)$_POST['student_id'],(int)$_POST['course_id'],$_POST['enrolled_on']]);header('Location: enrollments.php');exit;}catch(PDOException $e){$error='This student is already enrolled in this course.';}} $students=$pdo->query('SELECT id,roll_no,name FROM students ORDER BY name')->fetchAll();$courses=$pdo->query('SELECT id,code,title FROM courses ORDER BY code')->fetchAll();$rows=$pdo->query('SELECT e.id,e.enrolled_on,s.roll_no,s.name,c.code,c.title FROM enrollments e JOIN students s ON s.id=e.student_id JOIN courses c ON c.id=e.course_id ORDER BY e.id DESC')->fetchAll(); require 'includes/header.php'; ?>
<h2>Enrollments</h2><?php if($error):?><div class="alert alert-warning"><?=$error?></div><?php endif;?><div class="card shadow-sm p-3 mb-4"><form method="post" class="row g-2"><div class="col-md-4"><select required name="student_id" class="form-select"><option value="">Student</option><?php foreach($students as $s):?><option value="<?=$s['id']?>"><?=$s['roll_no']?> - <?=$s['name']?></option><?php endforeach;?></select></div><div class="col-md-4"><select required name="course_id" class="form-select"><option value="">Course</option><?php foreach($courses as $c):?><option value="<?=$c['id']?>"><?=$c['code']?> - <?=$c['title']?></option><?php endforeach;?></select></div><div class="col-md-3"><input required type="date" name="enrolled_on" value="<?=date('Y-m-d')?>" class="form-control"></div><div class="col-md-1"><button class="btn btn-primary">Add</button></div></form></div><div class="card shadow-sm"><table class="table"><thead><tr><th>Roll</th><th>Student</th><th>Course</th><th>Date</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['roll_no']?></td><td><?=$r['name']?></td><td><?=$r['code']?> - <?=$r['title']?></td><td><?=$r['enrolled_on']?></td><td><a data-confirm-delete class="btn btn-sm btn-danger" href="enrollments.php?delete=<?=$r['id']?>">Delete</a></td></tr><?php endforeach;?></tbody></table></div><?php require 'includes/footer.php'; ?>
